import{_ as t,o as n,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Documents générés","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/documents.md","filePath":"src/guide/documents.md"}'),o={name:"guide/documents.md"};function d(i,e,s,c,l,u){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="documents-generes" tabindex="-1">Documents générés <a class="header-anchor" href="#documents-generes" aria-label="Permalink to &quot;Documents générés&quot;">​</a></h1><p>Le module 32 rassemble tous les documents produits par Kura. Il n&#39;existe pas de table <code>document_genere</code> : chaque document est lu <strong>là où il est rangé</strong>, dans sa table métier, et « Mes documents » en dresse la liste pour un compte.</p><h2 id="le-catalogue" tabindex="-1">Le catalogue <a class="header-anchor" href="#le-catalogue" aria-label="Permalink to &quot;Le catalogue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Référence</th><th>Généré quand</th><th>Signataires</th></tr></thead><tbody><tr><td>Convention de formation</td><td><code>CONV-NB-AAAA-XXX</code></td><td>Contre-signature edPage</td><td>Apprenant (ou représentant légal), edPage</td></tr><tr><td>Convention tripartite</td><td><code>CONVT-NB-AAAA-XXX</code></td><td>Après la convention, si un financeur est désigné</td><td>Apprenant, financeur, edPage</td></tr><tr><td>Convention de stage</td><td><code>CONVS-NB-AAAA-XXX</code></td><td>À l&#39;envoi par le Coordinateur</td><td>Apprenant (ou représentant légal), entreprise, edPage</td></tr><tr><td>Livret d&#39;accueil</td><td><code>LA-NB-AAAA-XXX</code></td><td>Paiement complet de la 1re tranche</td><td>Aucune signature</td></tr><tr><td>Facture</td><td><code>FAC-NB-AAAA-XXX</code></td><td>Émission de la tranche</td><td>—</td></tr><tr><td>Avoir</td><td><code>AV-NB-AAAA-XXX</code></td><td>Annulation ou remboursement</td><td>—</td></tr><tr><td>Certificat</td><td><code>CERT-NB-AAAA-XXX</code></td><td>Délivrance par le Coordinateur</td><td>Président du jury</td></tr><tr><td>Attestation partielle</td><td><code>ATP-NB-AAAA-XXX</code></td><td>Abandon avec au moins un bloc validé</td><td>Coordinateur</td></tr><tr><td>Relevé de compétences</td><td><code>REL-NB-AAAA-XXX</code></td><td>Avec le certificat ou l&#39;attestation</td><td>Coordinateur</td></tr><tr><td>Lettre de décision</td><td>—</td><td>Décision rendue</td><td>—</td></tr><tr><td>Calendrier de cohorte</td><td>—</td><td>À la demande</td><td>—</td></tr><tr><td>Rapport d&#39;activité</td><td>—</td><td>À la demande</td><td>—</td></tr><tr><td>Procès-verbal de soutenance</td><td><code>PVS-NB-AAAA-XXX</code></td><td>Décisions du jury confirmées</td><td>Jury</td></tr></tbody></table><p>Tous les PDF sont générés côté serveur avec <code>barryvdh/laravel-dompdf</code>, stockés sur un disque <strong>privé</strong> et protégés par une empreinte SHA-256. Une facture ou un certificat émis ne se réédite pas : il se corrige par un avoir ou un remplacement.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><h3 id="convention-de-formation" tabindex="-1">Convention de formation <a class="header-anchor" href="#convention-de-formation" aria-label="Permalink to &quot;Convention de formation&quot;">​</a></h3><p>Le Coordinateur publie le texte des conditions générales en <strong>versions immuables</strong>. Une nouvelle version ne vaut que pour les signatures suivantes ; chaque convention signée garde la sienne. Sans texte publié, aucune signature n&#39;est possible.</p><p>Kura ajoute les conditions particulières : parties, référentiel, cohorte, format, prix HT et échéancier 30/40/30 aux dates de la cohorte. La signature est ouverte quand le dossier est complet (cohorte, consentements).</p><h3 id="convention-tripartite" tabindex="-1">Convention tripartite <a class="header-anchor" href="#convention-tripartite" aria-label="Permalink to &quot;Convention tripartite&quot;">​</a></h3><p>Préparée à la contre-signature d&#39;une convention de formation avec financeur, dont elle reprend les mentions. Le financeur la signe par code depuis « Apprenants financés » ; edPage contre-signe selon le réglage de l&#39;Administrateur. Elle ne bloque ni l&#39;inscription ni la facturation.</p><h3 id="convention-de-stage" tabindex="-1">Convention de stage <a class="header-anchor" href="#convention-de-stage" aria-label="Permalink to &quot;Convention de stage&quot;">​</a></h3><p>Le Coordinateur saisit l&#39;entreprise d&#39;accueil, son contact signataire, le Coach-Tuteur qui encadre le stage, les dates et la mission, modifiables jusqu&#39;à la première signature. À l&#39;envoi :</p><ul><li>l&#39;apprenant signe par code dans son compte (son représentant légal par un lien de 7 jours s&#39;il est mineur) ;</li><li>l&#39;entreprise signe par un lien de 7 jours et un code, sans compte ;</li><li>edPage contre-signe ensuite.</li></ul><p>Le jury reprend le nom de l&#39;entreprise dans les décisions de soutenance.</p><h2 id="signature-electronique" tabindex="-1">Signature électronique <a class="header-anchor" href="#signature-electronique" aria-label="Permalink to &quot;Signature électronique&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mécanisme</th><th>Règle</th></tr></thead><tbody><tr><td>Code de signature</td><td>6 chiffres, envoyé par email, valable 15 minutes, 5 essais, usage unique, stocké hashé</td></tr><tr><td>Lien public</td><td>Usage unique, valable 7 jours, stocké hashé, remplacé par tout nouveau lien</td></tr><tr><td>Limite d&#39;envoi</td><td>5 codes par minute et par route</td></tr><tr><td>Scellement</td><td>Empreinte SHA-256 du PDF signé, conservée avec le document</td></tr><tr><td>Contre-signature</td><td>Automatique au nom du représentant edPage, ou manuelle par le Coordinateur selon le réglage</td></tr><tr><td>Journalisation</td><td>Signature et contre-signature horodatées, avec nom, email, IP et navigateur</td></tr></tbody></table><p>Un mineur ne signe jamais lui-même : son représentant légal reçoit un lien distinct de celui des consentements, et le code part à son adresse.</p><h2 id="livret-d-accueil-et-documents-de-cohorte" tabindex="-1">Livret d&#39;accueil et documents de cohorte <a class="header-anchor" href="#livret-d-accueil-et-documents-de-cohorte" aria-label="Permalink to &quot;Livret d&#39;accueil et documents de cohorte&quot;">​</a></h2><ul><li>Le <strong>livret d&#39;accueil</strong> est généré après le paiement complet de la première tranche, un par convention. Il est envoyé par email et téléchargeable par l&#39;apprenant et le Coordinateur. Un changement de cohorte en produit un nouveau ; l&#39;ancien est conservé.</li><li>Le <strong>calendrier de cohorte</strong> liste blocs, dates clés, échéances, jours de jury et jours fériés. Il est disponible à la demande pour qui voit la cohorte.</li><li>Le <strong>rapport d&#39;activité</strong> (places, présence, résultats) est réservé au Coordinateur et à l&#39;Administrateur.</li><li>Le <strong>procès-verbal de soutenance</strong> est produit par la personne qui saisit le jury, une fois la soutenance de chaque apprenant confirmée. Il est scellé et conservé ; il n&#39;est régénéré que si les décisions du jury ont été corrigées, et le nouveau remplace l&#39;ancien, qui reste consultable.</li></ul><h2 id="acces-aux-documents" tabindex="-1">Accès aux documents <a class="header-anchor" href="#acces-aux-documents" aria-label="Permalink to &quot;Accès aux documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Acteur</th><th>Voit</th></tr></thead><tbody><tr><td>Apprenant</td><td>Ses conventions, livret, factures, avoirs, certificat, attestation, relevé, lettre de décision</td></tr><tr><td>Coordinateur</td><td>Les mêmes documents depuis la gestion des comptes et les pages métier</td></tr><tr><td>Financeur</td><td>La convention tripartite et les factures de sa part</td></tr><tr><td>Entreprise de stage</td><td>La convention de stage, par lien, sans compte</td></tr><tr><td>Représentant légal</td><td>Les consentements, la convention et la convention de stage, par lien</td></tr><tr><td>Direction</td><td>Les documents agrégés dans les tableaux de bord, sans pièces individuelles</td></tr></tbody></table><p>Les documents sont disponibles en français et en anglais, dans la langue du destinataire.</p><h2 id="conservation" tabindex="-1">Conservation <a class="header-anchor" href="#conservation" aria-label="Permalink to &quot;Conservation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Durée</th></tr></thead><tbody><tr><td>Conventions, factures, avoirs</td><td>10 ans (OHADA)</td></tr><tr><td>Certificats, attestations, relevés</td><td>Sans limite</td></tr><tr><td>Procès-verbaux de soutenance</td><td>Sans limite</td></tr></tbody></table><h2 id="technique" tabindex="-1">Technique <a class="header-anchor" href="#technique" aria-label="Permalink to &quot;Technique&quot;">​</a></h2><ul><li><code>App\\Services\\Documents\\DocumentLibrary</code> recense les documents d&#39;un compte.</li><li><code>App\\Http\\Controllers\\Documents\\*</code> sert « Mes documents » et les documents d&#39;un compte.</li><li><code>App\\Http\\Controllers\\Cohorts\\CohortDocumentController</code> produit calendrier, rapport d&#39;activité et procès-verbaux.</li><li><code>App\\Concerns\\SealsPdf</code> calcule et vérifie les empreintes.</li><li>Les vues PDF vivent dans <code>resources/views/pdf</code>, avec les modèles A et B des annexes.</li></ul>',27)])])}const h=t(o,[["render",d]]);export{m as __pageData,h as default};
